/bin/bash -lc "Rscript - <<'RS'
x <- readRDS('inputs/res_GluFevsGluFePlus.rds')
cat('attrs attempt\\n')
try({ a <- attributes(x); print(names(a)); str(a, max.level=1) })
cat('unclass attempt\\n')
try({ y <- unclass(x); print(class(y)); print(names(y)); str(y, max.level=2) })
cat('dput attr class only\\n')
try(dput(attributes(x)"'$class))
RS'

